// occulited task 75: the icon in a Control tile's circle, for the channel's current state - the KNX
// User Forum icon set (CC BY-SA 3.0 DE, ./knx/, regenerated by scripts/knx-icons.mjs), and the set's
// thermometer with a fill drawn into its tube (a modification of temp_temperature, so CC BY-SA as
// well) - every thermostat's icon since occulited task 97, whose valve shows as T2E's bar instead of
// the drawn gauge it had. The mapping follows
// the design spec of the task (the maintainer's final mock-up): the tone is the circle's accent -
// 'on' today's on colour, 'alarm' the error colour, '' the neutral one. A state change swaps the
// icon only; the circle keeps its box.
import {isOn, kindsOf, lockState, valvePercent, type Description, type Model, type Values} from './channels';
import {CONTACT_ICONS as CONTACT_NAMES, KEY_ICONS as KEY_NAMES, SWITCH_ICONS as SWITCH_NAMES} from '../../../scripts/knx-names.mjs';

const FILES = import.meta.glob('./knx/*.svg', {query: '?raw', import: 'default', eager: true}) as Record<string, string>;

/** the shipped icons by their name in the set */
export const KNX: Record<string, string> = Object.fromEntries(Object.entries(FILES).map(([f, svg]) => [f.replace(/^.*\/|\.svg$/g, ''), svg.trim()]));

// occulited task 102: the rest of the set, once the lazily loaded asset is in (knxall.ts); a chosen
// icon outside the bundle shows the automatic one until then
let extra: Record<string, string> = {};
/** Makes the whole set's drawings known to the tiles (the picker's loader calls it). */
export function registerExtraIcons(icons: Record<string, string>): void {
    extra = icons;
}
/** The drawing of a name: the bundle's, else the loaded set's, else undefined. */
export function knxSVG(name: string): string | undefined {
    return KNX[name] ?? extra[name];
}

export type Tone = '' | 'on' | 'alarm';
export interface StateIcon {
    /** the set's icon name, or thermometer:<0..100> for the drawn one (tests, data-icon) */
    name: string;
    svg: string;
    tone: Tone;
}
export interface IconInput {
    model: Model;
    values: Values;
    desc?: Description;
    /** the device's model (PARENT_TYPE), e.g. HmIP-PSM - a plug is a socket, not a lamp */
    parent?: string;
    /** a key's press shown as it happens */
    pressed?: boolean;
    /** occulited task 99: a switch's chosen icon (the metadata's control namespace; task 106: a key's too), and its shown name for the keyword defaults */
    icon?: string;
    name?: string;
    /** occulited task 105: a contact's chosen icons per state */
    icons?: ContactIcons;
}

function num(v: unknown): number | undefined {
    return typeof v === 'number' ? v : typeof v === 'string' && v !== '' && !isNaN(Number(v)) ? Number(v) : undefined;
}
const clamp = (x: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, x));
const f1 = (n: number) => n.toFixed(1);

/** The fill of the thermometer, 0..1: 12 °C and below empty, 25 °C and above full, linear between. */
export function thermoFill(celsius: number): number {
    return clamp((celsius - 12) / 13, 0, 1);
}

/** The set's thermometer with its tube filled to `p` (0..1). */
export function thermometerSVG(p: number): string {
    const top = 240 - 160 * clamp(p, 0, 1);
    const fill = `<rect x="160" y="${f1(top)}" width="19" height="${f1(240 - top)}" rx="3" fill="currentColor"/>`;
    return (KNX.temp_temperature ?? '<svg viewBox="0 0 361 361"></svg>').replace(/<\/svg>$/, `${fill}</svg>`);
}

/** A contact's state: closed, tilted or open (the value list names them; a plain one is open/closed). */
export function contactState(values: Values, desc: Description | undefined, key: string): 'closed' | 'tilted' | 'open' {
    const v = values[key];
    const list = desc?.[key]?.VALUE_LIST;
    if (list && typeof v === 'number') return list[v] === 'TILTED' ? 'tilted' : list[v] === 'OPEN' ? 'open' : 'closed';
    return v === true || (num(v) ?? 0) > 0 ? 'open' : 'closed';
}

// a plug-in switch actuator: a socket rather than a lamp
const SOCKET = /^(HmIP-PS|HM-LC-Sw\d-Pl|HM-ES-PMSw1-Pl)/i;
// a contact that can report tilted, or is mounted on a window
const WINDOW_KINDS = /^(WIN_SC|WIN_SC_SECURE|WIN_SC_SENSOR|RHS|WINDOW)$/;

// ---- occulited task 99: a switch's icon - chosen in the assignment sheet (stored in the metadata, the
// control namespace), else by a keyword in its name, else a plug's socket, else the light
/** The metadata namespace Control keeps a channel's choices in: {icon: "<a SWITCH_ICONS name>"}. */
export const CONTROL_NS = 'control';
/** The picker's suggested icons (the "off" name; light and socket have their own "on" picture). occulited task 102:
 *  any icon of the set may be chosen; these are the suggestions on top. */
export const SWITCH_ICONS: readonly string[] = SWITCH_NAMES;
/** occulited task 106: the suggestions for a key channel's icon; control_switch_1 is the default */
export const KEY_ICONS: readonly string[] = KEY_NAMES;
export const KEY_DEFAULT = 'control_switch_1';
/** occulited task 105: a door/window contact's states, and the suggestions for each */
export type ContactState = 'closed' | 'open' | 'tilted';
/** occulited task 110: a switch's states; its icons per state sit beside a contact's in the same `icons` key */
export type SwitchState = 'off' | 'on';
export type IconState = ContactState | SwitchState;
export type ContactIcons = Partial<Record<IconState, string>>;
export const SWITCH_STATES: readonly SwitchState[] = ['off', 'on'];
export const CONTACT_STATES: readonly ContactState[] = ['closed', 'open', 'tilted'];
export const CONTACT_ICONS: readonly string[] = CONTACT_NAMES;
/** today's icon of a contact's state: a window's (a kind that can tilt, or is mounted on one) or a door's; a door
 *  opener's (the `door` widget) open picture is the key */
export function contactDefault(state: ContactState, window: boolean, opener = false): string {
    if (opener) return state === 'closed' ? 'fts_door' : 'fts_door_opener_key';
    if (window) return state === 'tilted' ? 'fts_window_1w_tilt' : state === 'open' ? 'fts_window_1w_open' : 'fts_window_1w';
    return state === 'closed' ? 'fts_door' : 'fts_door_open';
}
/** whether a contact channel is shown as a window (task 75's rule) */
export function isWindow(desc: Description | undefined, stateKey: string): boolean {
    return [...kindsOf(desc)].some((k) => WINDOW_KINDS.test(k)) || !!desc?.[stateKey]?.VALUE_LIST?.includes('TILTED');
}
/** whether a contact channel has a tilted state (a window handle's VALUE_LIST names it) */
export function hasTilted(desc: Description | undefined, stateKey: string): boolean {
    return !!desc?.[stateKey]?.VALUE_LIST?.includes('TILTED');
}
/** the chosen icon of a state, if its drawing is at hand, else the default */
function contactIcon(icons: ContactIcons | undefined, state: IconState, fallback: string): string {
    const c = icons?.[state];
    return c && knxSVG(c) !== undefined ? c : fallback;
}
const SWITCH_ON: Record<string, string> = {light_light_dim_00: 'light_light_dim_100', message_socket: 'message_socket_on_off'};
// the keywords, case-insensitive, the first match winning: German words also inside a compound
// ("Steckdosen Werkstatt", "Gartenpumpe"), the English ones as whole words ("Stefan" is no fan)
const KEYWORDS: [RegExp, string][] = [
    [/steckdose|standby|\b(socket|plug)s?\b/i, 'message_socket'],
    [/ventilator|l(ü|ue)fter|\bfans?\b/i, 'vent_ventilation'],
    [/pumpe|\bpumps?\b/i, 'sani_pump'],
];

/** The switch icon's name: the chosen one (if its drawing is at hand - the bundle's or the loaded set's), a keyword's,
 *  a plug's socket, the light. */
export function switchIconId(chosen: string | undefined, name: string, parent = ''): string {
    if (chosen && knxSVG(chosen) !== undefined) return chosen;
    for (const [re, id] of KEYWORDS) if (re.test(name)) return id;
    if (SOCKET.test(parent)) return 'message_socket';
    return 'light_light_dim_00';
}
/** occulited task 110: a switch's picture in a state when nothing is chosen for that state - the single `icon` (or the
 *  keyword's, the socket, the light), with its "on" picture where the set has one */
export function switchStateDefault(state: SwitchState, chosen: string | undefined, name: string, parent = ''): string {
    const id = switchIconId(chosen, name, parent);
    return state === 'on' ? (SWITCH_ON[id] ?? id) : id;
}
/** The chosen icon in an object's metadata, or undefined. */
export function chosenIcon(meta: Record<string, unknown> | undefined): string | undefined {
    const ns = meta?.[CONTROL_NS] as {icon?: unknown} | undefined;
    return typeof ns?.icon === 'string' ? ns.icon : undefined;
}
/** occulited task 105: a contact's chosen icons per state in an object's metadata ({} when none). */
export function chosenIcons(meta: Record<string, unknown> | undefined): ContactIcons {
    const ns = meta?.[CONTROL_NS] as {icons?: unknown} | undefined;
    const raw = ns?.icons;
    const out: ContactIcons = {};
    if (!raw || typeof raw !== 'object') return out;
    for (const st of [...CONTACT_STATES, ...SWITCH_STATES]) {
        const v = (raw as Record<string, unknown>)[st];
        if (typeof v === 'string' && v) out[st] = v;
    }
    return out;
}

function knx(name: string, tone: Tone = ''): StateIcon {
    return {name, svg: knxSVG(name) ?? KNX.weather_station_generic ?? '', tone};
}
function thermo(celsius: number | undefined, tone: Tone = ''): StateIcon {
    const p = celsius === undefined ? 0 : thermoFill(celsius);
    return {name: `thermometer:${Math.round(p * 100)}`, svg: thermometerSVG(p), tone};
}
const step10 = (fraction: number) => clamp(Math.round(fraction * 10) * 10, 0, 100);

/** The icon and accent for a tile's circle. */
export function stateIcon({model: m, values, desc, parent = '', pressed = false, icon, name = '', icons}: IconInput): StateIcon {
    const on = isOn(m, values, desc);
    const v = values[m.stateKey];
    switch (m.widget) {
        case 'switch':
            // task 110: a chosen picture per state (on, off), else the single icon (task 99) for both, coloured by state
            return knx(contactIcon(icons, on ? 'on' : 'off', switchStateDefault(on ? 'on' : 'off', icon, name, parent)), on ? 'on' : '');
        case 'dimmer': {
            const l = step10(num(v) ?? 0);
            return knx(`light_light_dim_${String(l).padStart(2, '0')}`, l > 0 || on ? 'on' : '');
        }
        case 'color':
            return knx('light_led_stripe_rgb', on ? 'on' : '');
        case 'blind': {
            // LEVEL 1 = open; the set counts the closed part, from 10 (there is no _0) to 100
            const closed = clamp(step10(1 - (num(v) ?? 0)), 10, 100);
            return knx(`fts_shutter_${closed}`, on ? 'on' : '');
        }
        case 'lock': {
            const st = lockState(values, desc, m.stateKey);
            return st === 'open' ? knx('fts_door_open', 'on') : st === 'unlocked' ? knx('fts_door_unlocked', 'on') : knx('fts_door_locked');
        }
        case 'door':
            // task 105: a chosen picture per state, else the door and the key
            return on ? knx(contactIcon(icons, 'open', 'fts_door_opener_key'), 'on') : knx(contactIcon(icons, 'closed', 'fts_door'));
        case 'button':
            // task 106: a chosen icon (any of the set whose drawing is at hand), else the switch symbol; lit while pressed
            return knx(icon && knxSVG(icon) !== undefined ? icon : KEY_DEFAULT, pressed ? 'on' : '');
        case 'thermostat': {
            // task 97: the thermometer for every thermostat, filled from the room temperature (the setpoint
            // without one); an open valve still tints the tile, the valve itself is T2E's bar
            const valve = valvePercent(values, desc);
            return thermo(num(values.ACTUAL_TEMPERATURE) ?? num(v), valve !== undefined && valve > 0 ? 'on' : '');
        }
        case 'contact': {
            // task 105: a chosen picture per state (closed, open, tilted), else task 75's window or door
            const st = contactState(values, desc, m.stateKey);
            const window = isWindow(desc, m.stateKey);
            return knx(contactIcon(icons, st, contactDefault(st, window)), st === 'closed' ? '' : 'on');
        }
        case 'motion':
            return on ? knx('message_presence_active', 'on') : knx('message_presence');
        case 'smoke':
            return knx('secur_smoke_detector', on ? 'alarm' : '');
        case 'signal':
            return on ? knx('secur_alarm_alarm', 'alarm') : knx('secur_alarm');
        case 'power':
            return knx('measure_power_meter', (num(v) ?? 0) > 0 ? 'on' : '');
        case 'reading':
            return readingIcon(values, desc);
    }
    return knx('weather_station_generic');
}

function readingIcon(values: Values, desc: Description | undefined): StateIcon {
    const kinds = kindsOf(desc);
    const has = (k: string) => (desc ? k in desc : false) || values[k] !== undefined;
    if (kinds.has('WATER_DETECTION_TRANSMITTER')) {
        const wet = ['MOISTURE_DETECTED', 'WATERLEVEL_DETECTED', 'ALARM_STATE'].some((k) => values[k] === true || values[k] === 1);
        return knx('sani_leakage', wet ? 'alarm' : '');
    }
    if (kinds.has('RAIN_DETECTION_TRANSMITTER') || has('RAINING')) return knx('weather_rain', values.RAINING === true ? 'on' : '');
    if (kinds.has('SOIL_MOISTURE_TRANSMITTER')) return knx('weather_humidity_soil');
    if (has('WIND_SPEED')) return knx('weather_wind_speed');
    const temp = num(values.ACTUAL_TEMPERATURE ?? values.TEMPERATURE);
    if (has('ACTUAL_TEMPERATURE') || has('TEMPERATURE')) return thermo(temp);
    if (has('HUMIDITY')) return knx('weather_humidity_rel');
    if (kinds.has('BRIGHTNESS_TRANSMITTER') || has('ILLUMINATION') || has('CURRENT_ILLUMINATION')) return knx('weather_light_meter');
    return knx('weather_station_generic');
}
